<script lang="ts">
  import { onMount } from 'svelte';
  import Dropdown, { type DropdownOption } from '$lib/components/ui/Dropdown.svelte';
  let requestType = $state('access');
  const requestOptions: DropdownOption[] = [{value:'access',label:'Access / copy of my data'},{value:'correction',label:'Correct inaccurate data'},{value:'erasure',label:'Erase data / account deletion review'},{value:'blocking',label:'Block or restrict processing'},{value:'portability',label:'Data portability'},{value:'objection',label:'Object to processing'},{value:'withdraw-consent',label:'Withdraw consent where consent is the basis'},{value:'other',label:'Other privacy concern'}];
  let details = $state('');
  let busy = $state(false);
  let notice = $state('');
  let failed = $state(false);
  let requests = $state<Array<{ id: string; requestType: string; details: string | null; status: string; resolutionNote: string | null; createdAt: string }>>([]);
  let signedIn = $state(false);
  async function loadRequests() {
    try { const response = await fetch('/api/privacy-requests'); const result = await response.json(); if (response.ok) { requests = result.requests ?? []; signedIn = true; } }
    catch { /* privacy page is still readable while offline */ }
  }
  async function submitRequest() {
    if (busy) return; busy = true; notice = '';
    try {
      const response = await fetch('/api/privacy-requests', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ requestType, details }) });
      const result = await response.json(); if (!response.ok) throw new Error(result.error || 'Could not submit data request.');
      notice = result.message || 'Request recorded.'; failed = false; details = ''; await loadRequests();
    } catch (error) { notice = error instanceof Error ? error.message : 'Could not submit request.'; failed = true; }
    finally { busy = false; }
  }
  onMount(() => { void loadRequests(); });
</script>
<div class="mx-auto max-w-[920px] px-4 pb-14 sm:px-6">
  <header class="surface-card rounded-[1.5rem] p-6 sm:p-8"><p class="text-[10px] font-extrabold uppercase tracking-[.18em] text-indigo-200">PRIVACY & DATA RIGHTS</p><h1 class="mt-2 text-3xl font-extrabold tracking-tight text-white">Your data should remain under your control.</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-slate-400">This draft notice describes the current Nexus implementation. Before public launch, replace the operator and contact placeholders, perform a privacy impact assessment, determine the lawful bases and retention schedule, and have Philippine privacy counsel or a qualified DPO review it.</p></header>
  <section class="surface-card mt-4 rounded-[1.4rem] p-5 sm:p-7"><h2 class="text-lg font-extrabold text-white">Privacy notice</h2><div class="prose-nexus mt-4 space-y-4 text-sm leading-7 text-slate-400"><p><b class="text-slate-200">Data controller.</b> The site operator for Nexus is <span class="text-amber-200">[insert registered operator name and address]</span>. Privacy contact / DPO: <span class="text-amber-200">[insert monitored privacy email and DPO contact, if applicable]</span>. Do not launch with these placeholders.</p><p><b class="text-slate-200">Data we process.</b> Depending on how you use the service, this may include account identifiers, email, profile fields, posts, replies, votes, follows, bookmarks, community memberships, reports, support requests, moderation outcomes, public media metadata, security logs, and service-use events used for feed ranking. Avoid posting sensitive personal information unless necessary and lawful.</p><p><b class="text-slate-200">Purposes and legal basis.</b> Data may be processed to create and operate accounts, provide requested features, keep the service secure, prevent abuse, respond to support requests, meet legal obligations, and handle legal claims. The operator must document the applicable lawful basis for each purpose under the Philippine Data Privacy Act, and must not assume consent is the only possible lawful basis.</p><p><b class="text-slate-200">Feed personalization.</b> The For You feed uses interactions such as votes, clicks, replies, follows, shares, bookmarks, and negative feedback. You can switch feed modes and mute keywords. Those controls personalize ranking; they do not guarantee that no information is inferred from use.</p><p><b class="text-slate-200">Media storage.</b> Photos, videos, and audio can be uploaded directly to the operator's configured Backblaze B2 bucket using short-lived upload URLs. The production configuration should use a private bucket and short-lived signed downloads. Uploaded content can still be viewed by its intended audience and by storage administrators with infrastructure access; public social media is not private by default.</p><p><b class="text-slate-200">Direct messages.</b> Nexus encrypts message contents on the sender's browser using Web Crypto before storing ciphertext, with a separately encrypted content-key envelope per conversation member. The database API has no plaintext message-body field. The server still relays encrypted records and sees participant IDs, message timing, sizes, and related metadata. Key verification is trust-on-first-use and fingerprint verification is provided; the browser app is still delivered by the server, so a malicious or compromised deployment could serve altered client code. Lost browser keys are not recoverable in this version. When you deliberately report a message, the selected decrypted text is sent to moderators as evidence; unrelated messages are not submitted automatically.</p><p><b class="text-slate-200">Sharing other people's information.</b> Only upload or post photos, videos, personal information, or identifying details when you have the rights and lawful basis to do so. Do not post non-consensual intimate images, doxxing material, credentials, or private communications without a lawful reason.</p><p><b class="text-slate-200">Processors and transfers.</b> Hosting, PostgreSQL, authentication, email, and object-storage vendors may process data for the operator. The operator must inventory these providers, document their roles, review contracts and security guarantees, disclose relevant international transfers, and ensure appropriate safeguards.</p><p><b class="text-slate-200">Retention and safeguards.</b> Retain personal information only for a documented and justified period, delete or anonymize it when no longer needed unless law or a valid claim requires retention, restrict employee access, protect secrets and backups, and keep audit records. Reports and moderation records may be retained for proportionate safety, appeals, security, or legal purposes.</p><p><b class="text-slate-200">Security incidents.</b> The operator will assess incidents, contain threats, preserve evidence, and determine whether NPC and affected-person notification is required under applicable rules. Where the legal breach-notification criteria are met, the implementation plan must support the applicable 72-hour notification period from awareness / reasonable belief, not treat it as a blanket deadline for every security alert.</p><p><b class="text-slate-200">Children.</b> The operator must decide the permitted minimum age, implement age-appropriate safeguards, and obtain specialist review for any service aimed at or likely to be used by children. Do not claim child-safety compliance until actual procedures exist.</p></div></section>
  <section class="surface-card mt-4 rounded-[1.4rem] p-5 sm:p-7"><h2 class="text-lg font-extrabold text-white">Exercise a data subject right</h2><p class="mt-2 text-sm leading-6 text-slate-400">You can request access, correction, erasure, blocking, portability, object to particular processing, or ask a question. Requests are queued for review; the operator may need to verify identity and consider lawful retention obligations before acting. An erasure request is not automatically executed by this web form.</p><div class="mt-4 flex flex-wrap gap-3"><a href="/api/privacy-requests/export" class="action-link">Download my data export ↗</a><a href="/support" class="action-link">Contact privacy support ↗</a></div><form class="mt-5 grid gap-4" onsubmit={(event) => { event.preventDefault(); submitRequest(); }}><label class="field">Request type<Dropdown label="Request type" value={requestType} options={requestOptions} onChange={(value) => requestType = value} fullWidth /></label><label class="field">Details (optional)<textarea bind:value={details} maxlength="2500" rows="4" class="control" placeholder="Tell us which account or information this concerns. Don't include passwords or private keys."></textarea></label>{#if notice}<p class={`rounded-xl border px-3 py-2 text-xs ${failed ? 'border-rose-300/10 text-rose-100' : 'border-emerald-300/10 text-emerald-100'}`} role="status">{notice}</p>{/if}<div class="flex flex-wrap items-center justify-between gap-3"><span class="text-[10px] text-slate-600">{signedIn ? 'Signed-in request history is available below.' : 'Sign in before submitting a data rights request.'}</span><button disabled={busy} class="rounded-xl bg-indigo-300 px-5 py-3 text-xs font-extrabold text-slate-950 disabled:opacity-50">{busy ? 'Submitting…' : 'Submit request ↗'}</button></div></form>
  </section>
  {#if requests.length}<section class="surface-card mt-4 rounded-[1.4rem] p-5 sm:p-7"><h2 class="text-lg font-extrabold text-white">Your request history</h2><div class="mt-4 space-y-2">{#each requests as request}<article class="flex flex-wrap items-start justify-between gap-3 rounded-xl border border-white/[0.06] p-3"><div><p class="text-xs font-bold capitalize text-slate-200">{request.requestType.replaceAll('-', ' ')}</p><p class="mt-1 text-[10px] text-slate-600">Submitted {new Date(request.createdAt).toLocaleString()}</p>{#if request.resolutionNote}<p class="mt-2 text-xs text-slate-400">{request.resolutionNote}</p>{/if}</div><span class="rounded-full border border-white/10 px-2.5 py-1 text-[10px] text-slate-400">{request.status}</span></article>{/each}</div></section>{/if}
  <section class="mt-4 rounded-[1.3rem] border border-white/[0.06] bg-white/[0.015] p-5"><h2 class="text-sm font-extrabold text-white">Your rights in the Philippines</h2><p class="mt-2 text-xs leading-6 text-slate-500">Republic Act No. 10173 and its implementing rules provide rights including being informed, access, correction, objection, erasure or blocking where applicable, data portability, damages, and filing a complaint with the National Privacy Commission. Whether a specific right applies and how it is fulfilled depends on the request and applicable law. See the <a href="https://privacy.gov.ph/data-privacy-act-/" rel="noreferrer" target="_blank" class="text-indigo-200 hover:text-white">Data Privacy Act</a> and <a href="https://privacy.gov.ph/data-subject-rights/" rel="noreferrer" target="_blank" class="text-indigo-200 hover:text-white">NPC data subject rights</a>.</p></section>
</div>
<style>.field{display:grid;gap:8px;color:#a7b1c5;font-size:11px;font-weight:700}.control{width:100%;border:1px solid rgba(255,255,255,.08);border-radius:12px;background:rgba(0,0,0,.2);padding:11px 12px;color:#e2e8f0;font-size:13px;font-weight:400;outline:none}.control:focus{border-color:rgba(156,167,255,.35)}.control::placeholder{color:#5b667b}.action-link{display:inline-flex;border:1px solid rgba(165,180,252,.16);border-radius:11px;background:rgba(129,140,248,.06);padding:10px 12px;color:#c7d2fe;font-size:11px;font-weight:700}.action-link:hover{background:rgba(129,140,248,.12)}a{ text-decoration: none }</style>
